(6743961, 1010393, 30982, '<td valign="top">Lovely composition, nice use of light, and a very appropriate intepretation - headless with a blank page.  Nicely done.</td>', 'Lovely composition, nice use of light, and a very appropriate intepretation - headless with a blank page.  Nicely done.', '2012-04-16 23:11:58.000000', NULL, 1),
(6743962, 1010312, 30982, '<td valign="top">Ha!  What an excellent interpretation!</td>', 'Ha!  What an excellent interpretation!', '2012-04-16 23:12:18.000000', NULL, 1),
(6743963, 1009207, 30982, '<td valign="top">A soft, gentle poignancy to this.  An arrow shows us the way as we shuffle off this mortal coil, and all the while things get fuzzier... Wonderful interpretation!</td>', 'A soft, gentle poignancy to this.  An arrow shows us the way as we shuffle off this mortal coil, and all the while things get fuzzier... Wonderful interpretation!', '2012-04-16 23:13:49.000000', NULL, 1),
(6743968, 1010428, 30982, '<td valign="top">The body language comes across pretty well - it definitely feels isolated!  The techical quality needs a bit of work.  It''s hard to distinguish the shirt from the pants with both so dark - a bit more light might help that.  It seems to be a bit dark overall which can contribute to mood but here just seems to be too dark (if that makes sense.)  Stairwells usually have lousy lighting.  :-)  My monitor shows quite a bit of blockiness in some areas - usually a result of processing - most will not see it (my monitor is VERY bright) - it might be from trying to lighten a picture that was too dark to begin with, or shooting at very high ISO.</td>', 'The body language comes across pretty well - it definitely feels isolated!  The techical quality needs a bit of work.  It''s hard to distinguish the shirt from the pants with both so dark - a bit more light might help that.  It seems to be a bit dark overall which can contribute to mood but here just seems to be too dark (if that makes sense.)  Stairwells usually have lousy lighting.  :-)  My monitor shows quite a bit of blockiness in some areas - usually a result of processing - most will not see it (my monitor is VERY bright) - it might be from trying to lighten a picture that was too dark to begin with, or shooting at very high ISO.', '2012-04-16 23:25:31.000000', NULL, 1),
(6743969, 1009650, 30982, '<td valign="top">Oh.  My kind of photo.  Thank you!</td>', 'Oh.  My kind of photo.  Thank you!', '2012-04-16 23:25:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6743971, 1009565, 30982, '<td valign="top">Ha!  The decals are entertaining...</td>', 'Ha!  The decals are entertaining...', '2012-04-16 23:26:14.000000', NULL, 1),
(6743983, 1010256, 30982, '<td valign="top">I could take this in a couple of ways.  I''ll keep my mind above the table, though.  Makes for a wonderful abstract, particularly the plaid shorts (or at least what I see as plaid shorts...)   And no one said how much of the head one had to cut off, just that there was to be a person, and to crop off their head.  Check, and check.</td>', 'I could take this in a couple of ways.  I''ll keep my mind above the table, though.  Makes for a wonderful abstract, particularly the plaid shorts (or at least what I see as plaid shorts...)   And no one said how much of the head one had to cut off, just that there was to be a person, and to crop off their head.  Check, and check.', '2012-04-16 23:45:22.000000', NULL, 1),
(6743984, 1010402, 30982, '<td valign="top">I like the choice to go toned monochrome with this.</td>', 'I like the choice to go toned monochrome with this.', '2012-04-16 23:45:49.000000', NULL, 1),
(6743985, 1010318, 30982, '<td valign="top">An intriguing pair.  I like the difference in textures in the shirts (and the mystery of the unbuttoned button.)  Nice light as well.</td>', 'An intriguing pair.  I like the difference in textures in the shirts (and the mystery of the unbuttoned button.)  Nice light as well.', '2012-04-16 23:46:53.000000', NULL, 1),
(6743986, 1010166, 30982, '<td valign="top">My goodness that''s a lot of newsprint!  Must weigh a ton!  I like the crispness, and all the little details - the N on the shoe, the glvoes on the can, the keys fromt he pocket, the spiderweb tattoo - a very fun photograph to explore.  And all without heads.</td>', 'My goodness that''s a lot of newsprint!  Must weigh a ton!  I like the crispness, and all the little details - the N on the shoe, the glvoes on the can, the keys fromt he pocket, the spiderweb tattoo - a very fun photograph to explore.  And all without heads.', '2012-04-16 23:48:14.000000', NULL, 1),
(6743987, 1010358, 30982, '<td valign="top">This feels like a nice European spring evening, as the light gets longer, the days warmer, and the yard work begins.  Great mood you''ve created.</td>', 'This feels like a nice European spring evening, as the light gets longer, the days warmer, and the yard work begins.  Great mood you''ve created.', '2012-04-16 23:48:58.000000', NULL, 1),
(6743988, 1010252, 30982, '<td valign="top">Ha!  Definitely no heads in a scrum!  Technically a bit weak (muddy/lacking crisp detail) but good choice to go with B&amp;W, I think.</td>', 'Ha!  Definitely no heads in a scrum!  Technically a bit weak (muddy/lacking crisp detail) but good choice to go with B&W, I think.', '2012-04-16 23:50:19.000000', NULL, 1),
(6743989, 1010360, 30982, '<td valign="top">Lovely purples - I like the falling petals.  Title suits it well.</td>', 'Lovely purples - I like the falling petals.  Title suits it well.', '2012-04-16 23:50:43.000000', NULL, 1),
(6743991, 1010422, 30982, '<td valign="top">Great call!  Great shot, too.  Works very well for the challenge and a nice standalone photo.</td>', 'Great call!  Great shot, too.  Works very well for the challenge and a nice standalone photo.', '2012-04-16 23:51:11.000000', NULL, 1),
(6743992, 1010325, 30982, '<td valign="top">Ha!!!  VERY fun picture.</td>', 'Ha!!!  VERY fun picture.', '2012-04-16 23:51:33.000000', NULL, 1),
(6743994, 1009537, 30982, '<td valign="top">I like the long shadow.  Nice touch with the dust/smoke.</td>', 'I like the long shadow.  Nice touch with the dust/smoke.', '2012-04-16 23:52:08.000000', NULL, 1),
(6743995, 1010003, 30982, '<td valign="top">I''m still trying to figure your secret.  It can''t just be that you have cobbles, and soft light, and wonderful characters who wander around holding giant bouquets of flowers upside down, past perfectly manicured planters and fine wood doors.  But somehow you manage to add a perfectly performing cat at just the right point in time.  His back leg aloft as the gentleman''s foot steps down.  I''m beginning to think you have this HUGE soundstage setup somewhere and you direct all these people, with teams of makeup artists, light guys, prop departments, etc.  Because you''ve definitely used up more than your fair share of serendipity!</td>', 'I''m still trying to figure your secret.  It can''t just be that you have cobbles, and soft light, and wonderful characters who wander around holding giant bouquets of flowers upside down, past perfectly manicured planters and fine wood doors.  But somehow you manage to add a perfectly performing cat at just the right point in time.  His back leg aloft as the gentleman''s foot steps down.  I''m beginning to think you have this HUGE soundstage setup somewhere and you direct all these people, with teams of makeup artists, light guys, prop departments, etc.  Because you''ve definitely used up more than your fair share of serendipity!', '2012-04-16 23:55:17.000000', NULL, 1),
(6743998, 1010373, 30982, '<td valign="top">How lovely!  A very nice way to interpret this challenge.</td>', 'How lovely!  A very nice way to interpret this challenge.', '2012-04-16 23:56:10.000000', NULL, 1),
(6743999, 1010253, 30982, '<td valign="top">Ha!  I''m assuming the t-shirt is inhabited by the human.  But one never knows these days...</td>', 'Ha!  I''m assuming the t-shirt is inhabited by the human.  But one never knows these days...', '2012-04-16 23:57:17.000000', NULL, 1),
(6744000, 1010395, 30982, '<td valign="top">Ah, the quiet grab-and-smoke break.  The tryst of the outcasts.</td>', 'Ah, the quiet grab-and-smoke break.  The tryst of the outcasts.', '2012-04-16 23:59:12.000000', NULL, 1),
(6744022, 1010253, 91342, '<td valign="top">Cute.  Not sure it fits the topic; but, I do like it.</td>', 'Cute.  Not sure it fits the topic; but, I do like it.', '2012-04-17 00:27:23.000000', NULL, 1),
(6744024, 1009922, 91342, '<td valign="top">Very clever idea.  That is a bunch of axes!!</td>', 'Very clever idea.  That is a bunch of axes!!', '2012-04-17 00:28:14.000000', NULL, 1),
(6744026, 1010347, 91342, '<td valign="top">The tie is crooked! Nice idea.</td>', 'The tie is crooked! Nice idea.', '2012-04-17 00:28:59.000000', NULL, 1),
(6744027, 1010092, 91342, '<td valign="top">Clothing colors make this image for me.</td>', 'Clothing colors make this image for me.', '2012-04-17 00:29:20.000000', NULL, 1),
(6744033, 1010268, 91342, '<td valign="top">Took awhile to figure this out.  Was it candid or staged?  Like the idea.</td>', 'Took awhile to figure this out.  Was it candid or staged?  Like the idea.', '2012-04-17 00:32:40.000000', NULL, 1),
(6744036, 1010432, 30982, '<td valign="top">Chicken.  :-)</td>', 'Chicken.  :-)', '2012-04-17 00:44:21.000000', NULL, 1),
(6744037, 1009822, 30982, '<td valign="top">I like the mishmash of textures and patterns in this.  Might not be quite what folks expected for the challenge (ie his head isn''t cropped) but he does have his head disguised from view!</td>', 'I like the mishmash of textures and patterns in this.  Might not be quite what folks expected for the challenge (ie his head isn''t cropped) but he does have his head disguised from view!', '2012-04-17 00:45:02.000000', NULL, 1),
(6744040, 1010329, 30982, '<td valign="top">Ha!  Nice opportunity!  Bit of a snapshot (which if you know me isn''t a bad thing) but meets the challenge.</td>', 'Ha!  Nice opportunity!  Bit of a snapshot (which if you know me isn''t a bad thing) but meets the challenge.', '2012-04-17 00:47:11.000000', NULL, 1),
(6744042, 1010234, 30982, '<td valign="top">Nice combination of color/shape here.  I like that you left it in color because the red of the bikes is echoed in their clothing.</td>', 'Nice combination of color/shape here.  I like that you left it in color because the red of the bikes is echoed in their clothing.', '2012-04-17 00:47:49.000000', NULL, 1),
(6744043, 1010357, 30982, '<td valign="top">Heh.  I''m sure you have several spares hanging around for different occasions.  :-)</td>', 'Heh.  I''m sure you have several spares hanging around for different occasions.  :-)', '2012-04-17 00:49:03.000000', NULL, 1),
(6744044, 1009649, 30982, '<td valign="top">Love the kid!  And the pile of manure.  :-)</td>', 'Love the kid!  And the pile of manure.  :-)', '2012-04-17 00:49:30.000000', NULL, 1),
(6744046, 1010377, 30982, '<td valign="top">Cute pregnancy shoot!  I do think the family would want the head in the shot, but this works for this challenge.</td>', 'Cute pregnancy shoot!  I do think the family would want the head in the shot, but this works for this challenge.', '2012-04-17 00:50:36.000000', NULL, 1),
(6744047, 1010268, 30982, '<td valign="top">Heh!  Nice find!  One wonders if he is trying to hide and doing a pretty poor job of it.  Kind of like when kids think if they have *their* eyes closed, you can''t see them!</td>', 'Heh!  Nice find!  One wonders if he is trying to hide and doing a pretty poor job of it.  Kind of like when kids think if they have *their* eyes closed, you can''t see them!', '2012-04-17 00:51:49.000000', NULL, 1),
(6744048, 1010314, 30982, '<td valign="top">LOL!!  What a HOOT!!  Thanks for the tiny violin mention, too!  :-)</td>', 'LOL!!  What a HOOT!!  Thanks for the tiny violin mention, too!  :-)', '2012-04-17 00:52:35.000000', NULL, 1),
(6744049, 1009825, 30982, '<td valign="top">Seems almost a bit too opportunistic of a grab without much thought.  Not that I don''t do that - I do!  But this one just doesn''t quite have the story your title seems to want to tell.  I see the loneliness of a shoe salesman, maybe.</td>', 'Seems almost a bit too opportunistic of a grab without much thought.  Not that I don''t do that - I do!  But this one just doesn''t quite have the story your title seems to want to tell.  I see the loneliness of a shoe salesman, maybe.', '2012-04-17 00:57:24.000000', NULL, 1),
(6744053, 1009658, 30982, '<td valign="top">Now that''s one way to crop a head!  I think most were looking for a real person.  Though if this IS a real person, you have some explaining to do...</td>', 'Now that''s one way to crop a head!  I think most were looking for a real person.  Though if this IS a real person, you have some explaining to do...', '2012-04-17 00:59:42.000000', NULL, 1),
(6744056, 1010347, 30982, '<td valign="top">My take would be that corporate greed is faceless, yes?  Though he''s clearly a 99%''er with only 10s and 1s.  :-)</td>', 'My take would be that corporate greed is faceless, yes?  Though he''s clearly a 99%''er with only 10s and 1s.  :-)', '2012-04-17 01:04:00.000000', NULL, 1),
(6744058, 1010424, 30982, '<td valign="top">A lovely wet day for a ride!  I love the cross angle, the light, the B&amp;W, and this is one of those where the headless nature adds a nice anonymity.</td>', 'A lovely wet day for a ride!  I love the cross angle, the light, the B&W, and this is one of those where the headless nature adds a nice anonymity.', '2012-04-17 01:05:45.000000', NULL, 1),
(6744059, 1010143, 30982, '<td valign="top">A bit misty - I like the peaceful green of the water.  One of those where I''m not quite sure the headless nature serves a purpose other than meeting the challenge.</td>', 'A bit misty - I like the peaceful green of the water.  One of those where I''m not quite sure the headless nature serves a purpose other than meeting the challenge.', '2012-04-17 01:07:08.000000', NULL, 1),
(6744060, 1009224, 30982, '<td valign="top">Hmm - interesting take!  Took me a minute, but very nicely placed and played.  You have a warped video collection, though....</td>', 'Hmm - interesting take!  Took me a minute, but very nicely placed and played.  You have a warped video collection, though....', '2012-04-17 01:08:17.000000', NULL, 1),
(6744064, 1010315, 30982, '<td valign="top">I''ve yet to figure the appeal of chess pieces for DPC assignments, but they are popular!  I like the tie alot.  I like the idea of the setup, but the board is at an odd height - one would expect it lower than chest height, unless he was holding it as if it were a tray and "serving" the board to the opponent.</td>', 'I''ve yet to figure the appeal of chess pieces for DPC assignments, but they are popular!  I like the tie alot.  I like the idea of the setup, but the board is at an odd height - one would expect it lower than chest height, unless he was holding it as if it were a tray and "serving" the board to the opponent.', '2012-04-17 01:09:32.000000', NULL, 1),
(6744065, 1010177, 30982, '<td valign="top">A nice take on relationships.</td>', 'A nice take on relationships.', '2012-04-17 01:10:03.000000', NULL, 1),
(6744066, 1009452, 30982, '<td valign="top">The buttoned up shirt has such a wonderful oddness here - one doesn''t expect such longing to displayed from a buttoned up sort.</td>', 'The buttoned up shirt has such a wonderful oddness here - one doesn''t expect such longing to displayed from a buttoned up sort.', '2012-04-17 01:11:43.000000', NULL, 1),
(6744085, 1010383, 30982, '<td valign="top">I like the lines and curves of this.  Perhaps a bit flat due to the lighting you had to work with, but a nice take on the challenge.</td>', 'I like the lines and curves of this.  Perhaps a bit flat due to the lighting you had to work with, but a nice take on the challenge.', '2012-04-17 01:43:52.000000', NULL, 1),
(6744087, 1010124, 30982, '<td valign="top">Nice street shot; makes us want to see the rest of the story.</td>', 'Nice street shot; makes us want to see the rest of the story.', '2012-04-17 01:47:45.000000', NULL, 1),
(6744089, 1009789, 30982, '<td valign="top">Heh!  Nice catch, fun story!</td>', 'Heh!  Nice catch, fun story!', '2012-04-17 01:48:12.000000', NULL, 1),
(6744090, 1010203, 30982, '<td valign="top">They don''t look very excited about the birthday, and somehow I find that amusing!</td>', 'They don''t look very excited about the birthday, and somehow I find that amusing!', '2012-04-17 01:48:57.000000', NULL, 1),
(6744091, 1009565, 91783, '<td valign="top">pike place! in seattle! i like it :)</td>', 'pike place! in seattle! i like it :)', '2012-04-17 01:49:05.000000', NULL, 1),
(6744092, 1010192, 30982, '<td valign="top">Nice take on the challenge!  I like the gentle processing to this, too.</td>', 'Nice take on the challenge!  I like the gentle processing to this, too.', '2012-04-17 01:50:05.000000', NULL, 1),
(6744097, 1009941, 30982, '<td valign="top">Sweet light and very nice use of it.</td>', 'Sweet light and very nice use of it.', '2012-04-17 01:54:30.000000', NULL, 1),
(6744098, 1010337, 30982, '<td valign="top">Nice light, good use of the human form.</td>', 'Nice light, good use of the human form.', '2012-04-17 01:54:50.000000', NULL, 1),
(6744101, 1010092, 30982, '<td valign="top">Heh - my first thought was "the perfect example of a holiday snapshot" but it has a more ominous feel to it than that.  Then I noticed the spelling of your title - if that wasn''t intentional it was prophetic.</td>', 'Heh - my first thought was "the perfect example of a holiday snapshot" but it has a more ominous feel to it than that.  Then I noticed the spelling of your title - if that wasn''t intentional it was prophetic.', '2012-04-17 01:57:13.000000', NULL, 1),
(6744102, 1009658, 49954, '<td valign="top">No person and no cropped head... so DNMC :(  4 otherwise, -3 for DNMC = 1<br/> <br/>Had this been a statue, it would not be grounds for a DQ.  If you removed your son''s head in Post processing, then that would be a reason for a DQ as that''s not allowed in Advanced Editing.<br/> <br/>Regardless, since it looks like a statue, you''re going to get people who, like me, think it DNMC because it appears to not be a real person.  But even it it looked like a person, cropping the head should be cropped by the frame, not edited out or hidden.<br/> <br/>I will say if you took this shot like this without Photoshop trickery then VERY WELL DONE! :)<br/> <br/>Hope this helps.</td>', 'No person and no cropped head... so DNMC :(  4 otherwise, -3 for DNMC = 1 Had this been a statue, it would not be grounds for a DQ.  If you removed your son''s head in Post processing, then that would be a reason for a DQ as that''s not allowed in Advanced Editing. Regardless, since it looks like a statue, you''re going to get people who, like me, think it DNMC because it appears to not be a real person.  But even it it looked like a person, cropping the head should be cropped by the frame, not edited out or hidden. I will say if you took this shot like this without Photoshop trickery then VERY WELL DONE! :) Hope this helps.', '2012-04-17 01:57:14.000000', NULL, 1),
(6744103, 1010333, 30982, '<td valign="top">Nice energy to this.</td>', 'Nice energy to this.', '2012-04-17 01:58:37.000000', NULL, 1),
(6744104, 1010335, 30982, '<td valign="top">The odd toning to this adds to the general oddness of it overall.  One does wonder what the heck is going on!</td>', 'The odd toning to this adds to the general oddness of it overall.  One does wonder what the heck is going on!', '2012-04-17 01:59:41.000000', NULL, 1),
(6744105, 1010401, 30982, '<td valign="top">I LOVE the ghosted pigeons!  Marvelous long exposure to get the folks to stay still while the birds danced.  And I love her shoes.</td>', 'I LOVE the ghosted pigeons!  Marvelous long exposure to get the folks to stay still while the birds danced.  And I love her shoes.', '2012-04-17 02:00:22.000000', NULL, 1),
(6744106, 1010317, 30982, '<td valign="top">The flip of hair gives this a reason to have the person headless.  Rest of the setup is very nicely done.</td>', 'The flip of hair gives this a reason to have the person headless.  Rest of the setup is very nicely done.', '2012-04-17 02:01:33.000000', NULL, 1),
(6744110, 1010368, 30982, '<td valign="top">Well that''s one way to skin the cat/remove the head!  I think he needs a glass of wine.  :-)</td>', 'Well that''s one way to skin the cat/remove the head!  I think he needs a glass of wine.  :-)', '2012-04-17 02:07:45.000000', NULL, 1),
(6744111, 1009623, 30982, '<td valign="top">Good catch, nice light!</td>', 'Good catch, nice light!', '2012-04-17 02:09:31.000000', NULL, 1),
(6744112, 1010426, 30982, '<td valign="top">Quirky!  Though I have to say that twig is in an odd place...</td>', 'Quirky!  Though I have to say that twig is in an odd place...', '2012-04-17 02:13:58.000000', NULL, 1),
(6744114, 1010090, 30982, '<td valign="top">Yes, you did catch one without a head!  The rest look rather bored.  Hopefully the guy with the missing head is having a better day.</td>', 'Yes, you did catch one without a head!  The rest look rather bored.  Hopefully the guy with the missing head is having a better day.', '2012-04-17 02:18:38.000000', NULL, 1),
(6744115, 1009425, 30982, '<td valign="top">I like the patchwork of stone - very colorful!</td>', 'I like the patchwork of stone - very colorful!', '2012-04-17 02:18:59.000000', NULL, 1),
(6744116, 1010420, 30982, '<td valign="top">Very classic and elegant.</td>', 'Very classic and elegant.', '2012-04-17 02:19:38.000000', NULL, 1),
(6744117, 1010296, 30982, '<td valign="top">Almost has a cheesy motel kinda feel to it.  Which works.</td>', 'Almost has a cheesy motel kinda feel to it.  Which works.', '2012-04-17 02:21:46.000000', NULL, 1),
(6744147, 1009650, 113156, '<td valign="top">Wonderful, great looking bike and all those lines.</td>', 'Wonderful, great looking bike and all those lines.', '2012-04-17 04:45:39.000000', NULL, 1),
(6744154, 1010143, 123833, '<td valign="top">My top for this challenge. Hope it does well.</td>', 'My top for this challenge. Hope it does well.', '2012-04-17 04:53:50.000000', NULL, 1),
(6744258, 1010314, 144365, '<td valign="top">You forgot to mention about some of the 99% continuously complaining about morONEs and trolls instead of going out there and doing what it takes to win.  Just like the real 99%, it''s easy to complain and talk in platitudes to get the masses moving rather then doing any actual work yourself.</td>', 'You forgot to mention about some of the 99% continuously complaining about morONEs and trolls instead of going out there and doing what it takes to win.  Just like the real 99%, it''s easy to complain and talk in platitudes to get the masses moving rather then doing any actual work yourself.', '2012-04-17 08:40:26.000000', NULL, 1),
(6744405, 1010256, 66384, '<td valign="top">I like this image, because of the simple good design and geometry. There is no head, but it doesn''t seem to meet the challenge very well, because there''s no body either, just a little glimpse of leg.</td>', 'I like this image, because of the simple good design and geometry. There is no head, but it doesn''t seem to meet the challenge very well, because there''s no body either, just a little glimpse of leg.', '2012-04-17 12:01:27.000000', NULL, 1),
(6744406, 1009207, 66384, '<td valign="top">I like the way his shoulders blend into the background, as if the old man is walking into nirvana.</td>', 'I like the way his shoulders blend into the background, as if the old man is walking into nirvana.', '2012-04-17 12:11:49.000000', NULL, 1),
(6744413, 1009537, 66384, '<td valign="top">Terrific lighting. I love the long shadow on the stairs, the shadow on the wall, and the mist/smoke. Film noir!</td>', 'Terrific lighting. I love the long shadow on the stairs, the shadow on the wall, and the mist/smoke. Film noir!', '2012-04-17 12:21:53.000000', NULL, 1),
(6744415, 1010420, 66384, '<td valign="top">Beautiful light, beautiful tones, beautiful form. 10</td>', 'Beautiful light, beautiful tones, beautiful form. 10', '2012-04-17 12:23:31.000000', NULL, 1),
(6744417, 1009822, 66384, '<td valign="top">Compelling image! Doesn''t quite meet the challenge, IMHO, since the head has not been cropped from the image. True, his face is covered, but this is about not showing the head.</td>', 'Compelling image! Doesn''t quite meet the challenge, IMHO, since the head has not been cropped from the image. True, his face is covered, but this is about not showing the head.', '2012-04-17 12:29:12.000000', NULL, 1),
(6744422, 1009941, 113156, '<td valign="top">Sumptuous photo, what a swagger.</td>', 'Sumptuous photo, what a swagger.', '2012-04-17 12:36:44.000000', NULL, 1),
(6744423, 1010360, 66384, '<td valign="top">Adorable! I love the way the falling petals mimic the dress, in design and color.</td>', 'Adorable! I love the way the falling petals mimic the dress, in design and color.', '2012-04-17 12:37:22.000000', NULL, 1),
(6744424, 1010220, 113156, '<td valign="top">The dogs wearing jeans, fantastic shot.</td>', 'The dogs wearing jeans, fantastic shot.', '2012-04-17 12:39:36.000000', NULL, 1),
